$error=null;$success=null;$user=null;$csrf='';$categories=[];$products=[];$edit=null;$editPrices=[];$tierDefs=[];

function pmm_text(string $key,string $fallback=''): string{return trim((string)($_POST[$key]??$fallback));}
function pmm_decimal(string $key,?float $fallback=null): ?float{
    $raw=trim((string)($_POST[$key]??''));
    if($raw==='')return $fallback;
    if(!is_numeric($raw))throw new RuntimeException('Enter a valid number for '.str_replace('_',' ',$key).'.');
    return (float)$raw;
}
function pmm_upload_image(string $sku): ?array{
    if(!isset($_FILES['product_image'])||!is_array($_FILES['product_image']))return null;
    $f=$_FILES['product_image'];$err=(int)($f['error']??UPLOAD_ERR_NO_FILE);if($err===UPLOAD_ERR_NO_FILE)return null;
    if($err!==UPLOAD_ERR_OK)throw new RuntimeException('Product image upload failed.');
    $size=(int)($f['size']??0);if($size<=0||$size>8*1024*1024)throw new RuntimeException('Product image must be 8 MB or smaller.');
    $tmp=(string)($f['tmp_name']??'');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;
    if(!$ext)throw new RuntimeException('Product image must be JPG, PNG or WEBP.');
    $dim=@getimagesize($tmp);if(!$dim||($dim[0]??0)<200||($dim[1]??0)<200)throw new RuntimeException('Product image must be at least 200 × 200 pixels.');
    $dir=dirname(__DIR__).'/uploads/product-images';if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('Product image folder could not be created.');
    $safe=strtolower(preg_replace('/[^A-Z0-9]+/i','',$sku)?:'product');$name=$safe.'-'.date('YmdHis').'-'.bin2hex(random_bytes(4)).'.'.$ext;$target=$dir.'/'.$name;
    if(!move_uploaded_file($tmp,$target))throw new RuntimeException('Product image could not be saved.');
    return ['path'=>'../uploads/product-images/'.$name,'target'=>$target];
}
function pmm_current_product(PDO $pdo,int $orgId,int $id): ?array{
    $s=$pdo->prepare("SELECT p.*,c.category_name,l.id listing_id,l.market_sku,pv.id price_version_id,pv.effective_from,pv.mrp,pv.volume_points,pv.source_reference,
        (SELECT image_url FROM product_images i WHERE i.product_id=p.id ORDER BY i.is_primary DESC,i.sort_order,i.id DESC LIMIT 1) image_url
        FROM products p LEFT JOIN product_categories c ON c.id=p.category_id
        LEFT JOIN product_market_listings l ON l.product_id=p.id AND l.organization_id=p.organization_id AND l.status='active'
        LEFT JOIN product_price_versions pv ON pv.id=(SELECT v.id FROM product_price_versions v WHERE v.organization_id=p.organization_id AND v.listing_id=l.id AND v.status='active' ORDER BY v.effective_from DESC,v.id DESC LIMIT 1)
        WHERE p.organization_id=? AND p.id=? LIMIT 1");$s->execute([$orgId,$id]);$r=$s->fetch();return $r?:null;
}
function pmm_tier_values(PDO $pdo,int $priceVersionId): array{
    if($priceVersionId<=0)return [];$s=$pdo->prepare("SELECT t.tier_code,tp.price_amount FROM product_tier_prices tp JOIN product_discount_tiers t ON t.id=tp.discount_tier_id WHERE tp.price_version_id=?");$s->execute([$priceVersionId]);$out=[];foreach($s->fetchAll() as $r)$out[(string)$r['tier_code']]=(float)$r['price_amount'];return $out;
}

try{
    $pdo=role_portal_db();role_portal_ensure($pdo);product_step11_ensure($pdo);security_step17_session_start();
