    $tierOrder=['PC_BRONZE'=>'Preferred Bronze','PC_SILVER'=>'Preferred Silver','PC_GOLD'=>'Preferred Gold','ASSOC_RETAIL'=>'Associate Retail','ASSOC_EARN_BASE'=>'Associate Earn Base','ASSOC_25'=>'Associate 25%','ASSOC_35'=>'Senior Consultant 35%','ASSOC_42'=>'Qualified Producer / Success Builder 42%','ASSOC_50'=>'Supervisor 50%','PU_PRICE'=>'PU Price'];
