        $productId=max(0,(int)($_POST['product_id']??0));$sku=strtoupper(pmm_text('sku'));$name=pmm_text('product_name');$short=pmm_text('short_name');$brand=pmm_text('brand_name','Herbalife');$description=pmm_text('description');$packSize=pmm_decimal('pack_size');$packUnit=pmm_text('pack_unit');$status=in_array(pmm_text('status','active'),['active','inactive'],true)?pmm_text('status','active'):'active';$effective=pmm_text('effective_from');$mrp=pmm_decimal('mrp');$vp=pmm_decimal('volume_points');$source=pmm_text('source_reference');$categoryId=max(0,(int)($_POST['category_id']??0));$newCategory=pmm_text('new_category');
        if($sku===''||strlen($sku)>100)throw new RuntimeException('Stock / SKU is required.');if(strlen($name)<2||strlen($name)>190)throw new RuntimeException('Product name is required.');if($effective===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$effective))throw new RuntimeException('Choose the price effective date.');if($mrp===null||$mrp<0)throw new RuntimeException('MRP is required and cannot be negative.');if($vp===null||$vp<0)throw new RuntimeException('Volume Points are required and cannot be negative.');if($packSize!==null&&$packSize<0)throw new RuntimeException('Pack size cannot be negative.');if($source==='')throw new RuntimeException('Enter the authoritative source/reference for this launch or price update.');
        $dup=$pdo->prepare("SELECT id FROM products WHERE organization_id=? AND sku=? AND id<>? LIMIT 1");$dup->execute([$orgId,$sku,$productId]);if($dup->fetchColumn())throw new RuntimeException('This Stock / SKU already belongs to another product.');
        if($newCategory!==''){
            if(strlen($newCategory)>150)throw new RuntimeException('Category name is too long.');$code=product_step11_slug($newCategory);if($code==='')throw new RuntimeException('New category name is invalid.');$sort=(int)$pdo->prepare("SELECT COALESCE(MAX(sort_order),0)+10 FROM product_categories WHERE organization_id=?")->execute([$orgId]);
            $q=$pdo->prepare("SELECT COALESCE(MAX(sort_order),0)+10 FROM product_categories WHERE organization_id=?");$q->execute([$orgId]);$sort=(int)$q->fetchColumn();$s=$pdo->prepare("INSERT INTO product_categories(organization_id,category_code,category_name,sort_order,status) VALUES(?,?,?,?,'active') ON DUPLICATE KEY UPDATE category_name=VALUES(category_name),status='active'");$s->execute([$orgId,$code,$newCategory,$sort]);$q=$pdo->prepare("SELECT id FROM product_categories WHERE organization_id=? AND category_code=? LIMIT 1");$q->execute([$orgId,$code]);$categoryId=(int)$q->fetchColumn();
        }
        if($categoryId<=0)throw new RuntimeException('Choose or create a product category.');$q=$pdo->prepare("SELECT COUNT(*) FROM product_categories WHERE organization_id=? AND id=?");$q->execute([$orgId,$categoryId]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Selected category is invalid.');
        $tierValues=[];foreach($tierDefs as $code=>$def){$raw=trim((string)($_POST['tier'][$code]??''));if($raw==='')continue;if(!is_numeric($raw)||(float)$raw<0)throw new RuntimeException($def['label'].' must be a non-negative number.');$tierValues[$code]=(float)$raw;}
        $uploaded=pmm_upload_image($sku);$createdNew=$productId<=0;$pdo->beginTransaction();
        try{
            if($createdNew){$productCode='HL-IN-'.$sku;$check=$pdo->prepare("SELECT COUNT(*) FROM products WHERE organization_id=? AND product_code=?");$check->execute([$orgId,$productCode]);if((int)$check->fetchColumn()>0)$productCode='HL-IN-'.$sku.'-'.strtoupper(bin2hex(random_bytes(2)));$s=$pdo->prepare("INSERT INTO products(organization_id,category_id,product_code,sku,product_name,short_name,brand_name,description,pack_size,pack_unit,status) VALUES(?,?,?,?,?,?,?,?,?,?,?)");$s->execute([$orgId,$categoryId,$productCode,$sku,$name,$short?:null,$brand?:null,$description?:null,$packSize,$packUnit?:null,$status]);$productId=(int)$pdo->lastInsertId();}
            else{$s=$pdo->prepare("UPDATE products SET category_id=?,sku=?,product_name=?,short_name=?,brand_name=?,description=?,pack_size=?,pack_unit=?,status=? WHERE organization_id=? AND id=?");$s->execute([$categoryId,$sku,$name,$short?:null,$brand?:null,$description?:null,$packSize,$packUnit?:null,$status,$orgId,$productId]);if($s->rowCount()===0){$q=$pdo->prepare("SELECT COUNT(*) FROM products WHERE organization_id=? AND id=?");$q->execute([$orgId,$productId]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Product record was not found.');}}
            $s=$pdo->prepare("INSERT INTO product_market_listings(organization_id,market_id,product_id,market_sku,source_reference,active_from,status) VALUES(?,?,?,?,?,?,'active') ON DUPLICATE KEY UPDATE market_sku=VALUES(market_sku),source_reference=VALUES(source_reference),active_from=LEAST(COALESCE(active_from,VALUES(active_from)),VALUES(active_from)),status='active'");$s->execute([$orgId,$marketId,$productId,$sku,$source,$effective]);$q=$pdo->prepare("SELECT id FROM product_market_listings WHERE organization_id=? AND market_id=? AND product_id=? LIMIT 1");$q->execute([$orgId,$marketId,$productId]);$listingId=(int)$q->fetchColumn();
            $s=$pdo->prepare("INSERT INTO product_price_versions(organization_id,listing_id,effective_from,mrp,volume_points,currency_code,source_reference,status) VALUES(?,?,?,?,?,'INR',?,'active') ON DUPLICATE KEY UPDATE mrp=VALUES(mrp),volume_points=VALUES(volume_points),currency_code='INR',source_reference=VALUES(source_reference),status='active'");$s->execute([$orgId,$listingId,$effective,$mrp,$vp,$source]);$q=$pdo->prepare("SELECT id FROM product_price_versions WHERE organization_id=? AND listing_id=? AND effective_from=? LIMIT 1");$q->execute([$orgId,$listingId,$effective]);$priceId=(int)$q->fetchColumn();
            $pdo->prepare("DELETE FROM product_tier_prices WHERE price_version_id=?")->execute([$priceId]);$s=$pdo->prepare("INSERT INTO product_tier_prices(price_version_id,discount_tier_id,price_amount,pricing_method) VALUES(?,?,?,'source_exact')");foreach($tierValues as $code=>$amount)$s->execute([$priceId,$tierDefs[$code]['id'],$amount]);
            if($uploaded){$pdo->prepare("UPDATE product_images SET is_primary=0 WHERE product_id=? AND is_primary=1")->execute([$productId]);$s=$pdo->prepare("INSERT INTO product_images(product_id,image_url,source_page_url,source_name,verification_status,verified_at,alt_text,is_primary,sort_order) VALUES(?, ?, NULL, ?, 'verified', NOW(), ?,1,0)");$s->execute([$productId,$uploaded['path'],'Authorized product launch/update upload',$name]);}
            $pdo->commit();
        }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($uploaded&&isset($uploaded['target']))@unlink($uploaded['target']);throw $e;}
        security_step17_audit($pdo,(int)$user['id'],$createdNew?'product_launch_created':'product_master_updated','product',$productId,['sku'=>$sku,'effective_from'=>$effective,'source_reference'=>$source,'exact_tiers'=>array_keys($tierValues),'image_uploaded'=>(bool)$uploaded]);
        $success=$createdNew?'New product launch added. It is now connected to the product catalog and customer storefront when Active.':'Product details and dated exact price version updated successfully.';$_GET['edit']=$productId;
    }

    $s=$pdo->prepare("SELECT id,category_name FROM product_categories WHERE organization_id=? AND status='active' ORDER BY sort_order,category_name");$s->execute([$orgId]);$categories=$s->fetchAll();
    $s=$pdo->prepare("SELECT p.id,p.sku,p.product_name,p.status,c.category_name,(SELECT MAX(v.effective_from) FROM product_market_listings l JOIN product_price_versions v ON v.listing_id=l.id AND v.organization_id=l.organization_id WHERE l.organization_id=p.organization_id AND l.product_id=p.id AND v.status='active') latest_effective FROM products p LEFT JOIN product_categories c ON c.id=p.category_id WHERE p.organization_id=? ORDER BY p.updated_at DESC,p.id DESC LIMIT 100");$s->execute([$orgId]);$products=$s->fetchAll();
