"><div><h2><?=$edit?'Update Product':'Add Newly Launched Product'?></h2><p><?=$edit?'Master details can be corrected and a dated exact price version can be added/updated.':'Use the official launch/price source. Do not estimate missing prices.'?></p></div><?php if($edit):?><a class="pmm-reset" href="product_master_manager.php">+ New Product</a><?php endif;?></div><div class="pmm-note" style="margin:12px 0"><b>Exact-price rule:</b> only enter a tier price when it is present in the authoritative source. Leave a missing tier blank; the system will show it as unlisted rather than calculating a percentage.</div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=product_h($csrf)?>"><input type="hidden" name="product_id" value="<?=(int)($edit['id']??0)?>"><div class="pmm-fields"><label class="pmm-field"><span>Stock / SKU *</span><input name="sku" required maxlength="100" value="<?=pmm_v($edit,'sku')?>"></label><label class="pmm-field"><span>Product Name *</span><input name="product_name" required maxlength="190" value="<?=pmm_v($edit,'product_name')?>"></label><label class="pmm-field"><span>Short Name</span><input name="short_name" maxlength="120" value="<?=pmm_v($edit,'short_name')?>"></label><label class="pmm-field"><span>Brand</span><input name="brand_name" maxlength="120" value="<?=pmm_v($edit,'brand_name','Herbalife')?>"></label><label class="pmm-field"><span>Existing Category *</span><select name="category_id"><option value="0">Choose category…</option><?php foreach($categories as $c):?><option value="<?=(int)$c['id']?>" <?=((int)($edit['category_id']??0)===(int)$c['id'])?'selected':''?>><?=product_h($c['category_name'])?></option><?php endforeach;?></select></label><label class="pmm-field"><span>Or Create New Category</span><input name="new_category" maxlength="150" placeholder="Only if category does not exist"></label><label class="pmm-field"><span>Pack Size</span><input name="pack_size" type="number" min="0" step="0.001" value="<?=pmm_v($edit,'pack_size')?>"></label><label class="pmm-field"><span>Pack Unit</span><input name="pack_unit" maxlength="40" placeholder="gms, ml, tablets, sachets…" value="<?=pmm_v($edit,'pack_unit')?>"></label><label class="pmm-field wide"><span>Description / Product Detail</span><textarea name="description" maxlength="8000"><?=pmm_v($edit,'description')?></textarea></label><label class="pmm-field"><span>Status</span><select name="status"><option value="active" <?=($edit['status']??'active')==='active'?'selected':''?>>Active — publish in catalog/store</option><option value="inactive" <?=($edit['status']??'')==='inactive'?'selected':''?>>Inactive — keep hidden</option></select></label><label class="pmm-field"><span>Product Image</span><input type="file" name="product_image" accept="image/jpeg,image/png,image/webp"><?php if(!empty($edit['image_url'])):?><img class="pmm-image" src="<?=product_h($edit['image_url'])?>" alt="Current product image"><?php endif;?></label><label class="pmm-field"><span>Price Effective Date *</span><input name="effective_from" type="date" required value="<?=pmm_v($edit,'effective_from',date('Y-m-d'))?>"></label><label class="pmm-field"><span>MRP (₹) *</span><input name="mrp" type="number" min="0" step="0.01" required value="<?=pmm_v($edit,'mrp')?>"></label><label class="pmm-field"><span>Volume Points (VP) *</span><input name="volume_points" type="number" min="0" step="0.001" required value="<?=pmm_v($edit,'volume_points')?>"></label><label class="pmm-field wide"><span>Authoritative Source / Reference *</span><input name="source_reference" required maxlength="255" placeholder="Example: India price list effective 01 Sep 2026 / official launch circular" value="<?=pmm_v($edit,'source_reference')?>"></label></div><h3 style="margin:18px 0 6px;font-size:.9rem">Exact Customer / Associate Prices</h3><div class="pmm-tier"><?php foreach($tierDefs as $code=>$def):?><label class="pmm-field"><span><?=product_h($def['label'])?></span><input type="number" min="0" step="0.01" name="tier[<?=product_h($code)?>]" value="<?=array_key_exists($code,$editPrices)?product_h((string)$editPrices[$code]):''?>" placeholder="Leave blank if not listed"></label><?php endforeach;?></div><div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:16px"><button class="pmm-save" type="submit"><?=$edit?'Save Product Update':'Add Product Launch'?></button><?php if($edit):?><a class="pmm-reset" href="product_detail.php?id=<?=(int)$edit['id']?>">Open Product Details</a><?php endif;?></div></form></section><aside class="pmm-card"><h2 style="margin-top:0;font-size:1rem">Recent Products</h2><p class="meta">Choose Edit to update master details or add the next official price version.</p><?php foreach($products as $p):?><div class="pmm-row"><div><b><?=product_h($p['sku'])?></b><small><?=product_h($p['category_name']??'Uncategorised')?></small></div><div><b><?=product_h($p['product_name'])?></b><small><?=product_h(strtoupper($p['status']))?><?=!empty($p['latest_effective'])?' • '.product_h(date('d M Y',strtotime($p['latest_effective']))):''?></small></div><a href="?edit=<?=(int)$p['id']?>">Edit →</a></div><?php endforeach;?></aside></div><div class="os-footer-note"><strong>New launch workflow:</strong> save the official product data here → Active product appears in catalog/storefront → image can be replaced later in Product Images → future price changes create/update a dated price version instead of overwriting the historical catalog.</div></main></div></body></html>
